 pairs={'service-routines-source/audit.json':'service-routines-source-audit.json','service-routines-native.snapshots.bin.xz':'service-routines-reference.snapshots.bin.xz','service-routines-native-results.json':'service-routines-differential-results.json','service-routines-source.log':'service-routines-differential.log','service-routines-native-frozen-results.json':'service-routines-strict-results.json','service-routines-strict.log':'service-routines-strict.log','service-routines-sanitize-frozen-results.json':'service-routines-sanitize-results.json','service-routines-sanitize.log':'service-routines-sanitize.log','service-routines-tests.log':'service-routines-tests.log','service-routines-freeze.log':'service-routines-freeze.log','service-routines-target-source.snapshots.bin.xz':'service-routines-target-source.snapshots.bin.xz','service-routines-target-results.json':'service-routines-target-results.json','service-routines-c64.log':'service-routines-c64.log','service-routines-vice-results.json':'service-routines-vice-results.json','service-routines.prg':'service-routines.prg','service-routines.map':'service-routines.map','service-routines-mailbox.bin':'service-routines-mailbox.bin','service-routines-monitor.log':'service-routines-monitor.log','service-routines-vice.log':'service-routines-vice.log','service-routines-vice.mon':'service-routines-vice.mon'}
